@include('wisatawan.ticket-purchase.styles')
<style>
.payment-grid{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(0,1fr);gap:24px;align-items:start}.payment-card{padding:24px;border-radius:0}.payment-main{display:grid;gap:18px;min-width:0}.payment-summary{min-width:0}.payment-card h2{border-bottom:1px solid var(--color-border);padding-bottom:18px;text-transform:uppercase;letter-spacing:.06em}.payment-instructions h2{text-transform:none;letter-spacing:0;border:0}.payment-summary-item{padding-block:12px;border-bottom:1px solid var(--color-border)}.payment-summary-item p{font-size:12px;color:var(--color-muted)}.payment-card h2{font-size:13px;font-weight:700;margin:0 0 18px}.payment-card p{line-height:1.7;margin:12px 0}.payment-card form{margin-top:20px}.payment-card label{display:block;font-weight:600;margin:14px 0 7px}.payment-card input:not([type=checkbox]),.payment-card textarea{width:100%;min-height:44px;padding:10px;border:1px solid #b8cfc1;border-radius:0;background:white}.payment-card input[type=checkbox]{width:18px;height:18px;flex-shrink:0;margin-top:4px}.payment-card .payment-check{display:flex;gap:10px;align-items:start;font-weight:400}.payment-card textarea{min-height:100px}.payment-qr{display:block;width:100%;max-width:240px;height:auto;margin:20px auto}.payment-notice{padding:12px;background:#fff9e9;border:1px solid #eee2bb;font-size:12px;border-radius:0;line-height:1.6}.payment-error{color:#9e2929;margin:6px 0;font-size:14px}.payment-history{margin:16px 0;padding:0;list-style:none}.payment-history li{border-bottom:1px solid #e0e9e2;padding:14px 0;overflow-wrap:anywhere}.payment-label{display:inline-block;padding:6px 12px;background:#e8f2eb;border-radius:0;font-size:13px;font-weight:600}.payment-meta{display:grid;gap:16px;margin:20px 0}.payment-meta dt{font-size:13px;color:#5a7064}.payment-meta dd{margin:4px 0 0;overflow-wrap:anywhere}.payment-amount{font-size:clamp(20px,2.2vw,28px);font-weight:700;line-height:1.35}.payment-methods{display:grid;grid-template-columns:1fr 1fr;gap:0}.payment-method-tabs span{padding:16px;text-align:center;font-weight:700;border:1px solid var(--color-border);color:var(--color-primary)}.payment-method-tabs span.selected{background:var(--color-primary);color:white}.payment-method-choice label:has(input:checked){background:#edf4ee;border-color:var(--color-primary)}.payment-methods label{padding:18px;border:1px solid #b8cfc1;border-radius:0;cursor:pointer}.payment-methods input{width:auto!important;min-height:auto!important;margin-right:8px}.payment-card button:disabled{opacity:.6;cursor:wait}.payment-status-note{font-size:14px;color:#5a7064}.payment-list{display:grid;gap:16px;margin-top:24px}.payment-row{display:flex;gap:20px;justify-content:space-between;align-items:center;flex-wrap:wrap}.payment-row h2{font-size:16px;overflow-wrap:anywhere}.payment-row p{margin:6px 0}.payment-issue{border-left:3px solid #b14b37;padding-left:12px}.payment-card a{text-underline-offset:3px}.payment-card .payment-proof-link{text-decoration:underline}.payment-feedback{margin:20px 0}.payment-history time{display:block;font-size:12px;color:#5a7064}
@media(max-width:700px){.payment-grid{grid-template-columns:minmax(0,1fr)}.payment-card{padding:20px}.payment-method-choice{grid-template-columns:1fr}.payment-method-tabs{grid-template-columns:1fr 1fr}.payment-amount{font-size:24px}}
</style>
